const crownsN = () => MAIN.filter(c => CROWNS[c.map]).length;
const stagesWon = () => CAMPAIGN.filter(c => c.map && STARS[c.map] > 0).length;
// [tab, [[id, name, how, icon, progress: counter name | () => number | null (an event), out of]]]
const ACH_TABS = [
  ['Campaign', [
    ['win1', 'First Victory', 'Win Greenvale', 'sunrise', () => STARS.vale > 0 ? 1 : 0, 1],
    ['win6', 'Halfway There', 'Win 6 stages', 'knight-banner', stagesWon, 6],
    ['chief', 'Chief Felled', 'Slay the Raider Chief', 'horned-helm', null, 1],
    ['warlord', "Warlord's End", 'Slay the Warlord', 'crowned-skull', null, 1],
    ['stars18', 'Rising Star', 'Earn 18 stars', 'star-medal', () => campStarsN(), 18],
    ['stars36', 'Star Lord', 'Earn all 36 stars', 'star-formation', () => campStarsN(), 36],
    ['hard1', 'Hard as Iron', 'Win a stage on Hard', 'laurel-crown', crownsN, 1],
    ['hardall', 'Crowned King', 'Win every stage on Hard', 'imperial-crown', crownsN, 12],
    // the bonus stages (Jack): one for each crown, one for all three
    ['bonus13', 'Rainmaker', 'Win the Scorched Meadow', 'desert', () => CROWNS.meadow ? 1 : 0, 1],
    ['bonus14', 'Blight Bane', 'Win the Blighted Isle', 'plague-doctor-profile', () => CROWNS.isle ? 1 : 0, 1],
    ['bonus15', 'Winter Lord', 'Win the Frozen Pass', 'snowflake-2', () => CROWNS.pass ? 1 : 0, 1],
    ['bonusall', 'Legend', 'Win all three bonus stages', 'open-treasure-chest', () => ['meadow', 'isle', 'pass'].filter(m => CROWNS[m]).length, 3],
  ]],
  ['Battle', [
    ['kill250', 'Raider Hunter', 'Slay 250 raiders', 'arrow-cluster', 'kills', 250],
    ['kill2000', 'Bane of Raiders', 'Slay 2,000 raiders', 'skull-crossed-bones', 'kills', 2000],
    ['volley50', 'Rain of Arrows', 'Fire 50 arrow volleys', 'striking-arrows', 'volleys', 50],
    ['rider100', 'Charge', 'Riders slay 100 raiders', 'cavalry', 'riders', 100],
    ['siege25', 'Siege Breaker', 'Break 25 siege engines', 'siege-ram', 'engines', 25],
    ['burn100', 'Trial by Fire', 'Burn 100 raiders', 'burning-skull', 'burns', 100],
    ['flawless', 'Flawless', 'Win a stage without losing a building', 'checked-shield', null, 1],
    ['laststand', 'Last Stand', 'Win with the castle below 10% health', 'cracked-shield', null, 1],
  ]],
  ['Town', [
    ['vill50', 'Thriving Town', 'Reach 50 villagers', 'village', 'vill', 50],
    ['build500', 'Master Builder', 'Build 500 buildings', 'hammer-nails', 'built', 500],
    ['castle3', 'Castle Lord', 'Upgrade the castle to tier 3', 'castle', null, 1],
    ['trade100', 'Merchant Prince', 'Trade 100 times at the market', 'shop', 'trades', 100],
    ['wood5k', 'Woodsman', 'Gather 5,000 wood', 'log', 'wood', 5000],
    ['stone5k', 'Stonemason', 'Gather 5,000 stones', 'stone-block', 'stone', 5000],
    ['food5k', 'Good Harvest', 'Grow 5,000 food', 'wheat', 'food', 5000],
    ['wall100', 'Great Wall', 'Build 100 walls', 'stone-wall', 'walls', 100],
  ]],
];
const ACH_ALL = ACH_TABS.flatMap(([t, l]) => l.map(a => ({ tab: t, id: a[0], name: a[1], how: a[2], ico: a[3], p: a[4], of: a[5] })));
var ACH = { done: {}, n: {} }; try { const o = JSON.parse(localStorage.getItem('mtd-ach') || '{}'); ACH = { done: o.done || {}, n: o.n || {} }; } catch (e) {}
let achSaveT = 0;
const achSave = () => { if (achSaveT) return; achSaveT = setTimeout(() => { achSaveT = 0; try { localStorage.setItem('mtd-ach', JSON.stringify(ACH)); } catch (e) {} }, 800); };
// only on a campaign stage that is being played (not the title's showcase, not the gallery)
const achOn = () => !!CAMP_MAPS[MAP] && !plainMap && !showcaseBuilt && !galleryOn;
const achVal = a => a.p === null ? (ACH.done[a.id] ? 1 : 0) : typeof a.p === 'string' ? (ACH.n[a.p] || 0) : a.p();
const achIsDone = a => !!ACH.done[a.id];
function achEarn(a) { if (ACH.done[a.id]) return; ACH.done[a.id] = 1; achSave(); achToastQ.push(a); achToastNext(); log(`<b>Achievement</b> · ${a.name}`, 'good'); }
// a counted one moved on: every achievement that counts it is checked
function achAdd(k, n = 1) { if (!achOn()) return; ACH.n[k] = (ACH.n[k] || 0) + n; achSave(); for (const a of ACH_ALL) if (a.p === k && !ACH.done[a.id] && ACH.n[k] >= a.of) achEarn(a); }
function achMax(k, n) { if (!achOn() || n <= (ACH.n[k] || 0)) return; ACH.n[k] = n; achSave(); for (const a of ACH_ALL) if (a.p === k && !ACH.done[a.id] && n >= a.of) achEarn(a); }
function achFlag(id) { if (!achOn()) return; const a = ACH_ALL.find(x => x.id === id); if (a) achEarn(a); }
// the ones worked out from the stars and crowns (after a game, and when the campaign opens)
function achCheck() { for (const a of ACH_ALL) if (typeof a.p === 'function' && !ACH.done[a.id] && a.p() >= a.of) achEarn(a); }
// pictures in the town's colour, like the upgrades'
const achIco = a => { const c = new THREE.Color(); c.setStyle(TEAM_PAL[TEAM.town]); const lt = '#' + c.clone().lerp(new THREE.Color(1, 1, 1), .45).getHexString();
  return (ACH_ICO[a.ico] || '').replace(/#9cc5ff/g, lt).replace(/#2f5faf/g, TEAM_PAL[TEAM.town]); };
// a gold note when one is earned, with the star sound, one at a time
const achToastQ = []; let achToastOn = false;
function achToastNext() {
  if (achToastOn || !achToastQ.length) return; const a = achToastQ.shift(), el = $('#achToast'); achToastOn = true;
  el.innerHTML = `<span class="atIco">${achIco(a)}</span><span class="atTx"><small>Achievement</small><b>${a.name}</b></span>`; el.hidden = false;
  // a tablet's scaled top panel reaches past the pill's usual spot, so it sits just under the panel there (Jack saw it over the chips)
  el.style.top = document.body.classList.contains('tablet') ? (document.querySelector('.panel').getBoundingClientRect().bottom + 10) + 'px' : '';
  el.classList.remove('show'); void el.offsetWidth; el.classList.add('show'); sfx('achieve');
  setTimeout(() => { el.classList.remove('show'); setTimeout(() => { el.hidden = true; achToastOn = false; achToastNext(); }, 400); }, 3200);
}
// ---- the Achievements screen (from the campaign screen), laid out like Upgrades but the whole list at once, no tabs (Jack):
// upright it scrolls down, on a phone held sideways two rows scroll right ----
let achSel = null;
function openAchievements() { sfx('click'); $('#achPick').replaceChildren(); $('#campaign').hidden = true; $('#achPick').hidden = false; achSel = null; renderAchievements(); matchUpZoom($('#achPick')); }
const achProg = a => { const v = Math.min(achVal(a), a.of); return achIsDone(a) ? 'Done' : a.of > 1 ? `${v.toLocaleString()} / ${a.of.toLocaleString()}` : 'Not yet'; };
function renderAchievements() {
  const all = ACH_ALL; if (!achSel) achSel = all[0].id;
  const el = $('#achPick'), got = ACH_ALL.filter(achIsDone).length;
  let sh = el.querySelector('.upSheet'); if (!sh) { sh = document.createElement('div'); sh.className = 'upSheet achSheet'; el.replaceChildren(sh); }
  sh.innerHTML = `<div class="upTop"><button class="upBack campBack" id="achBack" aria-label="Back"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19.5 12H5.5M11.5 5.5L5 12l6.5 6.5"/></svg></button><h2>Achievements</h2><div class="upBank"><span class="upNum"><b>${got}</b><i class="upAll">/ ${ACH_ALL.length}</i></span></div></div>
    <div class="achGrid">${all.map(a => { const d = achIsDone(a), f = Math.min(1, achVal(a) / a.of);
      return `<div class="achItem"><button class="achNode${d ? ' done' : ''}${a.id === achSel ? ' sel' : ''}" data-ach="${a.id}" aria-label="${a.name}">${achIco(a)}${d ? '<span class="upTick">✓</span>' : ''}</button><div class="achName">${a.name}</div>${!d && a.of > 1 ? `<div class="achBar"><u style="width:${f > 0 ? Math.max(3, f * 100) : 0}%"></u></div>` : ''}</div>`; }).join('')}</div>
    <div class="upDet achDet"><div class="upBig"></div><div class="upTx"><div class="upOf"></div><h3></h3><p></p><div class="achP"></div></div></div>`;
  selectAch(achSel);
}
function selectAch(id) {
  achSel = id; const el = $('#achPick'), a = ACH_ALL.find(x => x.id === id), d = achIsDone(a);
  for (const n of el.querySelectorAll('.achNode')) n.classList.toggle('sel', n.dataset.ach === id);
  const big = el.querySelector('.upBig'); big.innerHTML = achIco(a); big.classList.toggle('dim', !d);
  el.querySelector('.upOf').textContent = a.tab; el.querySelector('.upTx h3').textContent = a.name; el.querySelector('.upTx p').textContent = a.how;
  const p = el.querySelector('.achP'); p.textContent = achProg(a); p.classList.toggle('ok', d);
}
$('#achPick').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  if (b.id === 'achBack') { sfx('click'); $('#achPick').hidden = true; openCampaign(cSel); return; }
  if (b.dataset.ach) { sfx('click'); selectAch(b.dataset.ach); }
});
document.addEventListener('click', e => { if (e.target.closest('#campAchBtn')) openAchievements(); });
